// Exercises the real Store and workspace transaction with the original resolver's
// independently generated result. Package callbacks inspect a private test tree.
#[tokio::test(flavor = "current_thread")]
#[ignore = "requires records generated by the pinned original legacy migration"]
async fn legacy_recovery_revalidates_and_commits_the_original_successor() {
    use serde_json::{Value, json};
    use std::cell::Cell;

    let path = std::env::var_os("TOBKIRI_ORIGINAL_LEGACY_SUCCESSOR_FIXTURE").unwrap();
    let records: Value = serde_json::from_slice(&fs::read(path).unwrap()).unwrap();
    let predecessor = &records["activation"];
    let profile_id = predecessor["profile_id"].as_str().unwrap();
    let schemas = workspace_active::tests::bound_recovery_schemas();
    for case in [
        "unchanged",
        "epoch-during-verification",
        "artifact-mutated",
        "artifact-mutated-after-commit",
    ] {
        with_setup_source(|source, read, cancellation, budget| {
            let candidate = format!(
                r#"{{"activation_id": "{}", "profile_id": "{}"}}"#,
                predecessor["activation_id"].as_str().unwrap(),
                profile_id,
            );
            enter_profile_candidate(source, read, cancellation, &candidate, profile_id);
            initialize(source, read, cancellation);
            let workspace = source.root.join("workspaces").join(profile_id);
            let state = workspace.join("activation");
            fs::create_dir_all(state.join("activations")).unwrap();
            let workspace_digest = Digest::hash(
                &serde_json::to_vec(
                    &json!({"workspace_root":workspace.canonicalize().unwrap().to_str().unwrap()}),
                )
                .unwrap(),
            );
            let envelope = json!({
                "schema": "io.tobkiri.defaultspack-activation-envelope.v1",
                "workspace_digest": workspace_digest.as_str(),
                "profile": records["profile"], "lock": records["lock"],
                "plan": records["plan"], "activation": predecessor,
            });
            let envelope_bytes = serde_json::to_vec(&envelope).unwrap();
            fs::write(state.join("activations/legacy.json"), &envelope_bytes).unwrap();
            let pointer = json!({
                "schema": workspace_active::POINTER_SCHEMA,
                "workspace_digest": workspace_digest.as_str(),
                "activation_id": predecessor["activation_id"],
                "envelope_path": "legacy.json",
                "envelope_digest": Digest::hash(&envelope_bytes).as_str(),
            });
            let pointer_bytes = serde_json::to_vec(&pointer).unwrap();
            fs::write(state.join("active.json"), &pointer_bytes).unwrap();
            let db = Connection::open(source.root.join(DATABASE)).unwrap();
            db.execute(
                "INSERT INTO activation_reservations
                 (reservation_id,activation_id,profile_id,plan_digest,profile_authority_digest,
                  security_epoch,fencing_token,state,created_at,updated_at)
                 VALUES ('reservation:legacy',?,?,?,?,?,?,'active',1.0,1.0)",
                params![
                    predecessor["activation_id"].as_str().unwrap(),
                    profile_id,
                    predecessor["plan_digest"].as_str().unwrap(),
                    predecessor["profile_authority_snapshot_digest"]
                        .as_str()
                        .unwrap(),
                    predecessor["security_epoch"].as_i64().unwrap(),
                    predecessor["fencing_token"].as_i64().unwrap(),
                ],
            )
            .unwrap();
            for (key, value) in [
                (
                    "security_epoch",
                    predecessor["security_epoch"].as_i64().unwrap(),
                ),
                (
                    "activation_fencing_token",
                    predecessor["fencing_token"].as_i64().unwrap(),
                ),
            ] {
                db.execute(
                    "UPDATE authority_meta SET value=? WHERE key=?",
                    params![value.to_string(), key],
                )
                .unwrap();
            }
            let artifact_root = source.root.join("test-artifacts");
            fs::create_dir(&artifact_root).unwrap();
            fs::write(artifact_root.join("program"), b"original").unwrap();
            let parent = identity(&fs::metadata(&source.root).unwrap());
            let workspace_lock = state.join(LockName::workspace(profile_id).text());
            let resolution_count = Cell::new(0);
            let verification_count = Cell::new(0);
            let identity_count = Cell::new(0);
            let result = ready_test(read.run_recovery(
                source, cancellation, budget, Some(schemas),
                |_, _, _, _, _| unreachable!("no committed pending journal"),
                ActiveSnapshotChecks {
                    artifact: |_: &Operation<'_, Source>, _: &CoreValue, _: &str| {
                        assert!(lock_free(&workspace_lock));
                        Ok(ActiveArtifactVerification::Current)
                    },
                    definition: |_: &Operation<'_, Source>, _: &str, _: &str| {
                        unreachable!("obsolete Host intent is rejected before definition lookup")
                    },
                    legacy: async |input: LegacyResolverInput| {
                        assert!(!lock_free(&workspace_lock));
                        assert_eq!(input.profile_id.as_str(), Some(profile_id));
                        resolution_count.set(resolution_count.get() + 1);
                        Ok(Some(CoreValue::parse_guest(
                            &serde_json::to_vec(&records["legacy_successor"]).unwrap(), budget,
                        ).unwrap()))
                    },
                    legacy_artifact: |op: &Operation<'_, Source>, _: &CoreValue, _: &str| {
                        assert!(lock_free(&workspace_lock));
                        assert!(!lock_free(&source.root.join(LOCK_PATH)));
                        assert!(lock_free(&source.root.join(GUARD)));
                        verification_count.set(verification_count.get() + 1);
                        let identity = catalog::capture_artifact_identity(
                            op, budget, &artifact_root, "program", parent, None,
                        )?;
                        if case == "epoch-during-verification" {
                            db.execute("UPDATE authority_meta SET value=CAST(value AS INTEGER)+1 WHERE key='security_epoch'", []).unwrap();
                        }
                        if case == "artifact-mutated" {
                            fs::write(artifact_root.join("program"), b"replaced").unwrap();
                        }
                        Ok(identity)
                    },
                    legacy_identity: |op: &Operation<'_, Source>, _: &CoreValue, expected: &ArtifactTreeIdentity| {
                        assert!(!lock_free(&workspace_lock));
                        identity_count.set(identity_count.get() + 1);
                        if case == "artifact-mutated-after-commit" && identity_count.get() == 2 {
                            fs::write(artifact_root.join("program"), b"replaced after commit").unwrap();
                        }
                        let actual = catalog::capture_artifact_identity(
                            op, budget, &artifact_root, "program", parent, None,
                        )?;
                        catalog::require_artifact_identity(op, budget, expected, &actual)
                    },
                },
            ));
            let error = result.unwrap_err();
            assert_eq!(error.class, recovery_workspace::APP_DENIED);
            assert_eq!(verification_count.get(), 1);
            assert_eq!(
                resolution_count.get(),
                if case == "epoch-during-verification" {
                    1
                } else {
                    2
                }
            );
            assert_eq!(
                state.join("pending.json").exists(),
                case == "artifact-mutated-after-commit"
            );
            if case == "unchanged" {
                assert_eq!(error.message, "Profile publication candidate changed");
                assert_eq!(identity_count.get(), 2);
                let current: Value =
                    serde_json::from_slice(&fs::read(state.join("active.json")).unwrap()).unwrap();
                let name = current["envelope_path"].as_str().unwrap();
                let migrated: Value = serde_json::from_slice(
                    &fs::read(state.join("activations").join(name)).unwrap(),
                )
                .unwrap();
                for field in ["profile", "lock", "plan"] {
                    assert_eq!(migrated[field], records["legacy_successor"][field]);
                }
                assert_eq!(migrated["activation"], records["migrated_activation"]);
                assert_eq!(
                    current["envelope_digest"],
                    Digest::hash(&serde_json::to_vec(&migrated).unwrap()).as_str()
                );
            } else {
                assert_eq!(fs::read(state.join("active.json")).unwrap(), pointer_bytes);
                assert_eq!(
                    error.message,
                    if case.starts_with("artifact-mutated") {
                        "active Profile Shell artifact changed after verification"
                    } else {
                        "legacy activation predecessor is stale or tampered"
                    },
                );
            }
            let statuses: Vec<(String, String)> = db.prepare(
                "SELECT activation_id,state FROM activation_reservations ORDER BY fencing_token",
            ).unwrap().query_map([], |row| Ok((row.get(0)?, row.get(1)?))).unwrap()
                .map(Result::unwrap).collect();
            if matches!(case, "unchanged" | "artifact-mutated-after-commit") {
                assert_eq!(statuses.len(), 2);
                assert_eq!(statuses[0].1, "retired");
                assert_eq!(
                    statuses[1].0,
                    records["migrated_activation"]["activation_id"]
                        .as_str()
                        .unwrap()
                );
                assert_eq!(statuses[1].1, "active");
            } else {
                assert_eq!(statuses[0].1, "active");
                if case == "artifact-mutated" {
                    assert_eq!(statuses.len(), 2);
                    assert_eq!(statuses[1].1, "aborted");
                } else {
                    assert_eq!(statuses.len(), 1);
                }
            }
            verify_custody(source, read, cancellation, false);
            if case == "artifact-mutated-after-commit" {
                fs::write(artifact_root.join("program"), b"original").unwrap();
                let mut retry = PublicationRead::new(&read.invocation).unwrap();
                enter_profile_candidate(source, &mut retry, cancellation, &candidate, profile_id);
                let recovery = ready_test(retry.run_recovery(
                    source, cancellation, budget, Some(schemas),
                    |op, store, workspace, pending, id| {
                        assert!(lock_free(&workspace_lock));
                        assert_eq!(fs::read(artifact_root.join("program")).unwrap(), b"original");
                        let expected = catalog::capture_artifact_identity(
                            op, budget, &artifact_root, "program", parent, None,
                        )?;
                        pending.publish(op, store, workspace, id, budget, |_| {
                            assert!(!lock_free(&workspace_lock));
                            let actual = catalog::capture_artifact_identity(
                                op, budget, &artifact_root, "program", parent, None,
                            )?;
                            catalog::require_artifact_identity(op, budget, &expected, &actual)
                        })
                    },
                    ActiveSnapshotChecks {
                        artifact: |_: &Operation<'_, Source>, _: &CoreValue, _: &str| unreachable!(),
                        definition: |_: &Operation<'_, Source>, _: &str, _: &str| unreachable!(),
                        legacy: async |_| -> Result<Option<CoreValue>> { unreachable!() },
                        legacy_artifact: |_: &Operation<'_, Source>, _: &CoreValue, _: &str| -> Result<ArtifactTreeIdentity> { unreachable!() },
                        legacy_identity: |_: &Operation<'_, Source>, _: &CoreValue, _: &ArtifactTreeIdentity| unreachable!(),
                    },
                )).unwrap();
                assert_eq!(recovery, RecoveryAuthorityReached::RecoveredNone);
                assert!(!state.join("pending.json").exists());
                let current: Value =
                    serde_json::from_slice(&fs::read(state.join("active.json")).unwrap()).unwrap();
                assert_eq!(
                    current["activation_id"],
                    records["migrated_activation"]["activation_id"]
                );
                verify_custody(source, &mut retry, cancellation, true);
            }
        });
    }
}
